// Package runtime provides UltraPlan's generic agent runtime boundary.
package runtime

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	stdruntime "runtime"
	"sort"
	"strings"
	"time"

	"github.com/Antonio7098/agentwrap"
	agentwrapopencode "github.com/Antonio7098/agentwrap/opencode"

	"github.com/Antonio7098/ultraplan-go/internal/platform/config"
)

type Request struct {
	Prompt            string
	PromptRef         PromptReference
	TraceID           string
	ParentTraceID     string
	WorkDir           string
	SessionID         string
	SessionAction     string
	Provider          string
	Model             string
	Timeout           time.Duration
	Metadata          map[string]string
	RequireHealth     []string
	RequireCaps       []string
	Sandbox           string
	Permissions       string
	Policy            PermissionPolicy
	Validation        *agentwrap.ValidationSpec
	OnEvent           func(Event)
	Cache             CacheDirective
	RuntimeStorePath  string
	RuntimeStoreOwner string
}

// CacheDirective carries product-owned prompt boundary semantics to runtime
// adapters. The current OpenCode adapter preserves these values as request
// metadata; adapters with provider-native support can apply them directly.
type CacheDirective struct {
	Key             string
	BreakpointBytes int
	PrefixDigest    string
	Mode            string
}

// PromptReference identifies the exact product-owned prompt sent to a runtime.
// It intentionally carries identity rather than prompt contents.
type PromptReference struct {
	ID        string
	Version   string
	OwnerKind string
	OwnerID   string
	Purpose   string
	Checksum  string
}

type PermissionPolicy struct {
	Default             string
	Tools               map[string]string
	PathRules           []PermissionPathRule
	UnsupportedBehavior string
	Metadata            map[string]string
}

type PermissionPathRule struct {
	Path   string
	Action string
}

type Result struct {
	RunID            string
	SessionID        string
	SessionIDs       []string
	TurnID           string
	Status           string
	TerminalOutput   string
	Events           []Event
	EventStats       EventStats
	Memory           MemoryStats
	Artifacts        []Artifact
	Warnings         []string
	Attempts         []AttemptSummary
	Usage            Usage
	EstimatedCost    *CostEstimate
	Policy           PolicySummary
	Permissions      PermissionSummary
	Cleanup          CleanupSummary
	Validation       ValidationSummary
	Repair           RepairSummary
	Error            *Error
	StartedAt        time.Time
	FinishedAt       time.Time
	RuntimeStorePath string
}

type Event struct {
	ID                string
	RunID             string
	SessionID         string
	Time              time.Time
	Type              string
	Kind              string
	Payload           map[string]any
	RawPresent        bool
	RawSafe           bool
	RawOmitted        bool
	RawOmissionReason string
	RawSource         string
	RawEncoding       string
}

type EventStats struct {
	Total    int64
	Retained int
	Dropped  int64
	Limit    int
}

type MemoryStats struct {
	StartAllocBytes uint64
	PeakAllocBytes  uint64
	EndAllocBytes   uint64
	Samples         int64
}

type Artifact struct {
	ID          string
	URI         string
	Kind        string
	Description string
	Metadata    map[string]string
}

const retainedRuntimeEventLimit = 200

type Usage struct {
	InputTokensKnown      bool
	InputTokens           int64
	OutputTokensKnown     bool
	OutputTokens          int64
	TotalTokensKnown      bool
	TotalTokens           int64
	ReasoningTokensKnown  bool
	ReasoningTokens       int64
	CacheReadTokensKnown  bool
	CacheReadTokens       int64
	CacheWriteTokensKnown bool
	CacheWriteTokens      int64
	TurnsKnown            bool
	Turns                 int64
	Native                map[string]any
}

type CostEstimate struct {
	Amount   float64
	Currency string
	Estimate bool
	// Source records cost provenance: provider_reported, model_priced, or
	// unpriced. Empty when no cost was determined.
	Source string
}

type AttemptSummary struct {
	Attempt         int
	AttemptOnTarget int
	TargetIndex     int
	RunID           string
	Status          string
	Provider        string
	Model           string
	ErrorCategory   string
	ErrorDetail     string
	RateLimited     bool
	RetryAfter      time.Duration
}

type PolicySummary struct {
	FinalAttempt     int
	FinalTargetIndex int
	Exhausted        bool
	ExhaustedReason  string
	Decisions        []PolicyDecision
}

type PolicyDecision struct {
	Attempt     int
	TargetIndex int
	Kind        string
	Reason      string
	Detail      string
	Delay       time.Duration
}

type ValidationSummary struct {
	Configured bool
	Passed     bool
	Failures   int
	Errors     int
	Details    []string
}

type PermissionSummary struct {
	Mode               string
	PolicyID           string
	Default            string
	UnsupportedCount   int
	AuditCount         int
	UnsupportedReasons []string
}

type CleanupSummary struct {
	Attempted bool
	Completed bool
	Failed    bool
	Error     *Error
}

type RepairSummary struct {
	Configured             bool
	Attempted              bool
	MaxAttempts            int
	AttemptCount           int
	Exhausted              bool
	ExhaustedReason        string
	PermissionDenied       bool
	UnsupportedSameSession bool
}

type Error struct {
	Category    string
	Operation   string
	UserDetail  string
	DebugDetail string
	Provider    string
	Model       string
	RuntimeKind string
	ExitCode    *int
	Signal      string
	RetryAfter  time.Duration
	Metadata    map[string]string
}

type Runtime interface {
	StartRun(context.Context, Request) (Result, error)
	Health(context.Context, HealthRequest) (HealthReport, error)
	Capabilities(context.Context) (Capabilities, error)
}

type Adapter struct {
	runtime            agentwrap.Runtime
	health             agentwrap.HealthChecker
	deleteSession      func(context.Context, string) error
	deleteSessions     func(context.Context, []string) error
	deleteRuntimeStore func(context.Context, string) error
}

// DeleteSession removes a completed retained session and its runtime-owned
// messages, parts, and related records when the configured adapter supports it.
func (a Adapter) DeleteSession(ctx context.Context, sessionID string) error {
	if strings.TrimSpace(sessionID) == "" {
		return nil
	}
	if a.deleteSessions != nil {
		return a.deleteSessions(ctx, []string{sessionID})
	}
	if a.deleteSession == nil {
		return nil
	}
	return a.deleteSession(ctx, sessionID)
}

// DeleteSessions removes a completed batch and reclaims adapter-owned storage.
func (a Adapter) DeleteSessions(ctx context.Context, sessionIDs []string) error {
	if a.deleteSessions != nil {
		return a.deleteSessions(ctx, sessionIDs)
	}
	for _, sessionID := range sessionIDs {
		if err := a.DeleteSession(ctx, sessionID); err != nil {
			return err
		}
	}
	return nil
}

func (a Adapter) DeleteRuntimeStore(ctx context.Context, path string) error {
	if strings.TrimSpace(path) == "" || a.deleteRuntimeStore == nil {
		return nil
	}
	return a.deleteRuntimeStore(ctx, path)
}

func NewAdapter(aw agentwrap.Runtime) Adapter {
	a := Adapter{runtime: aw}
	if h, ok := aw.(agentwrap.HealthChecker); ok {
		a.health = h
	}
	return a
}

func (a Adapter) StartRun(ctx context.Context, req Request) (Result, error) {
	if a.runtime == nil {
		return Result{}, fmt.Errorf("runtime is required")
	}
	if req.RuntimeStorePath != "" {
		if err := prepareRuntimeStore(req.RuntimeStorePath, req.RuntimeStoreOwner); err != nil {
			return Result{RuntimeStorePath: req.RuntimeStorePath}, err
		}
	}
	awReq, err := toAgentwrapRequest(req)
	if err != nil {
		retainRuntimeStore(req.RuntimeStorePath, req.RuntimeStoreOwner, err)
		return Result{RuntimeStorePath: req.RuntimeStorePath}, err
	}
	run, err := a.runtime.StartRun(ctx, awReq)
	if err != nil {
		mappedErr := mapError(err)
		retainRuntimeStore(req.RuntimeStorePath, req.RuntimeStoreOwner, mappedErr)
		return Result{RuntimeStorePath: req.RuntimeStorePath}, mappedErr
	}

	eventsCh := make(chan eventCollection, 1)
	go func() {
		events := newEventCollection(retainedRuntimeEventLimit)
		for event := range run.Events() {
			events.captureTerminalOutput(event.Payload)
			mapped := mapEvent(event)
			events.add(mapped)
			if req.OnEvent != nil {
				req.OnEvent(mapped)
			}
		}
		events.finish()
		eventsCh <- events
	}()

	type waitResult struct {
		result agentwrap.RunResult
		err    error
	}
	waitCh := make(chan waitResult, 1)
	go func() {
		result, err := run.Wait(ctx)
		waitCh <- waitResult{result: result, err: err}
	}()

	var result agentwrap.RunResult
	var waitErr error
	select {
	case waited := <-waitCh:
		result = waited.result
		waitErr = waited.err
	case <-ctx.Done():
		_ = run.Cancel(context.Background())
		select {
		case waited := <-waitCh:
			result = waited.result
			waitErr = waited.err
		case <-time.After(5 * time.Second):
			mapped := Result{
				Status:           "cancelled",
				FinishedAt:       time.Now(),
				Error:            &Error{Category: "cancellation", Operation: "run", UserDetail: ctx.Err().Error()},
				RuntimeStorePath: req.RuntimeStorePath,
			}
			retainRuntimeStore(req.RuntimeStorePath, req.RuntimeStoreOwner, ctx.Err())
			return mapped, ctx.Err()
		}
		if waitErr == nil {
			waitErr = ctx.Err()
		}
	}

	mapped := mapResult(result)
	mapped.RuntimeStorePath = req.RuntimeStorePath
	select {
	case events := <-eventsCh:
		mapped.Events = events.events
		if mapped.TerminalOutput == "" && events.terminalOutput != "" {
			mapped.TerminalOutput = events.terminalOutput
		}
		mapped.EventStats = events.stats()
		mapped.Memory = events.memory
		mapped.SessionIDs = append([]string(nil), events.sessionIDs...)
		if mapped.SessionID != "" && !events.seenSessions[mapped.SessionID] {
			mapped.SessionIDs = append(mapped.SessionIDs, mapped.SessionID)
		}
		if events.dropped > 0 {
			mapped.Warnings = append(mapped.Warnings, fmt.Sprintf("runtime retained last %d events and dropped %d earlier events from in-memory result", events.limit, events.dropped))
		}
	case <-time.After(time.Second):
	}
	if waitErr != nil {
		retainRuntimeStore(req.RuntimeStorePath, req.RuntimeStoreOwner, waitErr)
		if errors.Is(waitErr, context.Canceled) {
			mapped.Status = "cancelled"
			mapped.Error = &Error{Category: "cancellation", Operation: "run", UserDetail: waitErr.Error()}
		} else if errors.Is(waitErr, context.DeadlineExceeded) {
			mapped.Status = "failed"
			mapped.Error = &Error{Category: "timeout", Operation: "run", UserDetail: waitErr.Error()}
		}
		return mapped, mapError(waitErr)
	}
	if result.Err != nil {
		retainRuntimeStore(req.RuntimeStorePath, req.RuntimeStoreOwner, result.Err)
		return mapped, mapError(result.Err)
	}
	retainRuntimeStore(req.RuntimeStorePath, req.RuntimeStoreOwner, nil)
	return mapped, nil
}

type eventCollection struct {
	events         []Event
	terminalOutput string
	total          int64
	dropped        int64
	limit          int
	memory         MemoryStats
	sessionIDs     []string
	seenSessions   map[string]bool
}

func newEventCollection(limit int) eventCollection {
	if limit < 0 {
		limit = 0
	}
	var mem stdruntime.MemStats
	stdruntime.ReadMemStats(&mem)
	return eventCollection{
		events:       make([]Event, 0, limit),
		limit:        limit,
		seenSessions: map[string]bool{},
		memory: MemoryStats{
			StartAllocBytes: mem.Alloc,
			PeakAllocBytes:  mem.Alloc,
			Samples:         1,
		},
	}
}

func (c *eventCollection) add(event Event) {
	c.total++
	if event.SessionID != "" && !c.seenSessions[event.SessionID] {
		c.seenSessions[event.SessionID] = true
		c.sessionIDs = append(c.sessionIDs, event.SessionID)
	}
	if c.total == 1 || c.total%64 == 0 {
		c.sampleMemory()
	}
	if c.limit == 0 {
		c.dropped++
		return
	}
	if len(c.events) < c.limit {
		c.events = append(c.events, event)
		return
	}
	copy(c.events, c.events[1:])
	c.events[len(c.events)-1] = event
	c.dropped++
}

func (c *eventCollection) captureTerminalOutput(payload map[string]any) {
	if value := terminalOutputValue(payload, 0); value != "" {
		c.terminalOutput = truncateString(value, maxMappedTerminalOutputBytes)
	}
}

func terminalOutputValue(value any, depth int) string {
	if depth > 4 {
		return ""
	}
	switch typed := value.(type) {
	case map[string]any:
		for _, key := range []string{"structured_output", "output", "content", "text", "message", "part"} {
			if nested, ok := typed[key]; ok {
				if result := terminalOutputValue(nested, depth+1); result != "" {
					return result
				}
			}
		}
	case []any:
		for i := len(typed) - 1; i >= 0; i-- {
			if result := terminalOutputValue(typed[i], depth+1); result != "" {
				return result
			}
		}
	case string:
		return typed
	}
	return ""
}

func (c *eventCollection) finish() {
	c.sampleMemory()
}

func (c *eventCollection) sampleMemory() {
	var mem stdruntime.MemStats
	stdruntime.ReadMemStats(&mem)
	c.memory.Samples++
	c.memory.EndAllocBytes = mem.Alloc
	if mem.Alloc > c.memory.PeakAllocBytes {
		c.memory.PeakAllocBytes = mem.Alloc
	}
}

func (c eventCollection) stats() EventStats {
	return EventStats{
		Total:    c.total,
		Retained: len(c.events),
		Dropped:  c.dropped,
		Limit:    c.limit,
	}
}

func (a Adapter) Capabilities(ctx context.Context) (Capabilities, error) {
	if a.runtime == nil {
		return Capabilities{}, fmt.Errorf("runtime is required")
	}
	caps, err := a.runtime.Capabilities(ctx)
	if err != nil {
		return Capabilities{}, mapError(err)
	}
	return mapCapabilities(caps), nil
}

func RequestFromConfig(c config.Config, workDir string) (Request, error) {
	timeout, err := time.ParseDuration(c.Execution.DefaultTimeout)
	if err != nil {
		return Request{}, err
	}
	provider, model := splitModel(c.Models.Primary)
	if provider == "" && model == "" {
		provider, model = splitModel(c.Models.Default)
	}
	return Request{
		WorkDir:       workDir,
		Provider:      provider,
		Model:         model,
		Timeout:       timeout,
		RequireHealth: append([]string(nil), c.Agentwrap.RequiredHealth...),
		RequireCaps:   append([]string(nil), c.Agentwrap.RequiredCapabilities...),
		Sandbox:       c.Agentwrap.Sandbox,
		Permissions:   c.Agentwrap.PermissionMode,
		Policy: PermissionPolicy{
			Default:             c.Agentwrap.PermissionDefault,
			UnsupportedBehavior: c.Agentwrap.PermissionUnsupportedBehavior,
		},
	}, nil
}

func toAgentwrapRequest(req Request) (agentwrap.RunRequest, error) {
	health, err := mapHealthIDs(req.RequireHealth)
	if err != nil {
		return agentwrap.RunRequest{}, err
	}
	caps, err := mapCapabilitiesIDs(req.RequireCaps)
	if err != nil {
		return agentwrap.RunRequest{}, err
	}
	policy, err := mapPermissionPolicy(req.Policy)
	if err != nil {
		return agentwrap.RunRequest{}, err
	}
	metadata := cloneStringMap(req.Metadata)
	if req.RuntimeStorePath != "" {
		if metadata == nil {
			metadata = map[string]string{}
		}
		metadata[agentwrapopencode.MetadataDatabasePath] = req.RuntimeStorePath
		metadata["runtime_store_owner"] = req.RuntimeStoreOwner
	}
	if req.Cache.Key != "" {
		if metadata == nil {
			metadata = map[string]string{}
		}
		cohort, _ := json.Marshal(struct {
			Foundation, Provider, Model, WorkDir, Sandbox, Permissions string
			Policy                                                     PermissionPolicy
		}{req.Cache.Key, req.Provider, req.Model, req.WorkDir, req.Sandbox, req.Permissions, req.Policy})
		sum := sha256.Sum256(cohort)
		metadata["prompt_cache_foundation_key"] = req.Cache.Key
		metadata["prompt_cache_key"] = "ultraplan-cohort-v1-" + hex.EncodeToString(sum[:16])
		metadata["prompt_cache_breakpoint_bytes"] = fmt.Sprintf("%d", req.Cache.BreakpointBytes)
		metadata["prompt_cache_prefix_sha256"] = req.Cache.PrefixDigest
		metadata["prompt_cache_mode"] = req.Cache.Mode
	}
	return agentwrap.RunRequest{
		Prompt:           req.Prompt,
		WorkDir:          req.WorkDir,
		SessionID:        agentwrap.SessionID(req.SessionID),
		SessionAction:    agentwrap.SessionAction(req.SessionAction),
		Provider:         agentwrap.ProviderID(req.Provider),
		Model:            agentwrap.ModelID(req.Model),
		Timeout:          req.Timeout,
		Metadata:         metadata,
		RequireHealth:    health,
		RequireCaps:      caps,
		Sandbox:          agentwrap.SandboxMode(req.Sandbox),
		Permissions:      agentwrap.PermissionMode(req.Permissions),
		PermissionPolicy: policy,
		Validation:       req.Validation,
	}, nil
}

func mapResult(result agentwrap.RunResult) Result {
	warnings := make([]string, 0, len(result.Warnings))
	for _, warning := range result.Warnings {
		warnings = append(warnings, truncateDiagnosticString(warning))
	}
	return Result{
		RunID:          string(result.RunID),
		SessionID:      string(result.SessionID),
		TurnID:         string(result.TurnID),
		Status:         string(result.Status),
		TerminalOutput: result.TerminalOutput,
		Artifacts:      mapArtifacts(result.Artifacts),
		Warnings:       warnings,
		Attempts:       mapAttempts(result.Metadata.Attempts),
		Usage:          mapUsage(result.Usage),
		EstimatedCost:  mapCost(result.Metadata.EstimatedCost, result.Metadata.CostSource),
		Policy:         mapPolicy(result.Metadata.Policy),
		Permissions:    mapPermissions(result.Metadata.Permissions),
		Cleanup:        mapCleanup(result.Metadata.Cleanup),
		Validation:     mapValidation(result.Metadata.Validation),
		Repair:         mapRepair(result.Metadata.Repair),
		Error:          mapSDKError(result.Err),
		StartedAt:      result.StartedAt,
		FinishedAt:     result.FinishedAt,
	}
}

func mapEvent(event agentwrap.Event) Event {
	rawPresent := event.Raw != nil
	rawSafe := rawPresent && event.Raw.Safe
	payload := cloneAnyMap(event.Payload)
	if runtimeContext, ok := event.Payload["context"].(agentwrap.RuntimeContext); ok {
		payload["provider"] = string(runtimeContext.Provider)
		payload["model"] = string(runtimeContext.Model)
		payload["harness"] = string(runtimeContext.RuntimeKind)
	}
	promoteObservablePayloadFields(payload)
	return Event{
		ID:                string(event.ID),
		RunID:             string(event.RunID),
		SessionID:         string(event.SessionID),
		Time:              event.Time,
		Type:              event.Type,
		Kind:              string(event.Kind()),
		Payload:           payload,
		RawPresent:        rawPresent,
		RawSafe:           rawSafe,
		RawOmitted:        rawPresent,
		RawOmissionReason: rawOmissionReason(rawPresent, rawSafe),
		RawSource:         rawSource(event.Raw),
		RawEncoding:       rawEncoding(event.Raw),
	}
}

// promoteObservablePayloadFields lifts nested runtime facts (tool names, titles,
// text deltas, statuses) to the payload top level so downstream consumers —
// run-loop progress summaries, durable run journals, and the web timeline — can
// read them without depending on adapter-specific nesting. Existing top-level
// values always win.
func promoteObservablePayloadFields(payload map[string]any) {
	if len(payload) == 0 {
		return
	}
	for _, key := range []string{"tool", "name", "title", "detail", "text", "delta", "output", "message", "state", "status", "action", "phase"} {
		if value, ok := payload[key].(string); ok && strings.TrimSpace(value) != "" {
			continue
		}
		if found := findNestedPayloadString(payload, key, 0); found != "" {
			payload[key] = found
		}
	}
}

func findNestedPayloadString(value any, want string, depth int) string {
	if depth > 4 {
		return ""
	}
	switch typed := value.(type) {
	case map[string]any:
		if s, ok := typed[want].(string); ok && strings.TrimSpace(s) != "" {
			return s
		}
		// Deterministic traversal for stable results across map orders.
		keys := make([]string, 0, len(typed))
		for k := range typed {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		for _, k := range keys {
			if found := findNestedPayloadString(typed[k], want, depth+1); found != "" {
				return found
			}
		}
	case []any:
		for _, item := range typed {
			if found := findNestedPayloadString(item, want, depth+1); found != "" {
				return found
			}
		}
	}
	return ""
}

func mapUsage(usage agentwrap.Usage) Usage {
	out := Usage{Native: cloneAnyMap(usage.Native)}
	if usage.InputTokens != nil {
		out.InputTokensKnown = true
		out.InputTokens = *usage.InputTokens
	}
	if usage.OutputTokens != nil {
		out.OutputTokensKnown = true
		out.OutputTokens = *usage.OutputTokens
	}
	if usage.TotalTokens != nil {
		out.TotalTokensKnown = true
		out.TotalTokens = *usage.TotalTokens
	}
	if usage.ReasoningTokens != nil {
		out.ReasoningTokensKnown = true
		out.ReasoningTokens = *usage.ReasoningTokens
	}
	if usage.CacheReadTokens != nil {
		out.CacheReadTokensKnown = true
		out.CacheReadTokens = *usage.CacheReadTokens
	}
	if usage.CacheWriteTokens != nil {
		out.CacheWriteTokensKnown = true
		out.CacheWriteTokens = *usage.CacheWriteTokens
	}
	if usage.Turns != nil {
		out.TurnsKnown = true
		out.Turns = *usage.Turns
	}
	return out
}

func mapError(err error) error {
	if err == nil {
		return nil
	}
	var sdk *agentwrap.SDKError
	if errors.As(err, &sdk) {
		bounded := *sdk
		bounded.UserDetail = redactDiagnosticString("sdk.user_detail", sdk.UserDetail)
		bounded.DebugDetail = redactDiagnosticString("sdk.debug_detail", sdk.DebugDetail)
		bounded.ResponseBody = redactDiagnosticString("sdk.response_body", sdk.ResponseBody)
		bounded.ResponseHeaders = cloneStringMap(sdk.ResponseHeaders)
		bounded.Metadata = cloneStringMap(sdk.Metadata)
		switch {
		case errors.Is(err, context.Canceled):
			bounded.Cause = context.Canceled
		case errors.Is(err, context.DeadlineExceeded):
			bounded.Cause = context.DeadlineExceeded
		default:
			bounded.Cause = nil
		}
		return &bounded
	}
	return err
}

func mapSDKError(err *agentwrap.SDKError) *Error {
	if err == nil {
		return nil
	}
	return &Error{
		Category:    string(err.Category),
		Operation:   err.Operation,
		UserDetail:  redactDiagnosticString("sdk.user_detail", err.UserDetail),
		DebugDetail: redactDiagnosticString("sdk.debug_detail", err.DebugDetail),
		Provider:    string(err.Provider),
		Model:       string(err.Model),
		RuntimeKind: string(err.RuntimeKind),
		ExitCode:    err.ExitCode,
		Signal:      err.Signal,
		RetryAfter:  err.RetryAfter,
		Metadata:    cloneStringMap(err.Metadata),
	}
}

func redactDiagnosticString(key, value string) string {
	return config.RedactValue(key, truncateDiagnosticString(value))
}

func splitModel(value string) (string, string) {
	for i, r := range value {
		if r == '/' {
			return value[:i], value[i+1:]
		}
	}
	return "", value
}

package runtime

import (
	"context"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"sync"
	"time"

	"github.com/Antonio7098/agentwrap"
	"github.com/Antonio7098/agentwrap/opencode"

	"github.com/Antonio7098/ultraplan-go/internal/platform/config"
)

var openCodeSessionCleanupMu sync.Mutex

// rateSnapshotDir returns the cache directory holding the model-rate snapshot
// shared across runs. An empty result disables persistence (memory-only).
func rateSnapshotDir() string {
	cache, err := os.UserCacheDir()
	if err != nil || cache == "" {
		return ""
	}
	return filepath.Join(cache, "ultraplan")
}

func NewOpenCode(c config.Config) (Adapter, error) {
	rateStore := agentwrap.NewRateTableStore(rateSnapshotDir())
	newRuntime := func(extraArgs ...string) *opencode.Runtime {
		args := append([]string(nil), c.Agentwrap.ExtraArgs...)
		args = append(args, extraArgs...)
		return opencode.NewRuntime(
			opencode.WithExecutable(c.Agentwrap.Executable),
			opencode.WithExtraArgs(args...),
			opencode.WithEnv(c.Agentwrap.Env...),
			opencode.WithSnapshots(false),
			opencode.WithStderrLimit(c.Agentwrap.StderrLimit),
			opencode.WithRateTableStore(rateStore),
		)
	}
	primary := newRuntime()
	stageRuntime := requestVariantRuntime{
		base: primary,
		withVariant: func(variant string) agentwrap.Runtime {
			return newRuntime("--variant", variant)
		},
	}
	policy := agentwrap.BasicPolicy{
		MaxAttemptsPerTarget: c.Execution.DefaultRetries + 1,
		Backoff:              agentwrap.ExponentialBackoff{Initial: time.Second, Factor: 2, Max: 30 * time.Second},
		RetryRateLimits:      true,
	}
	if c.Models.Backup != "" && c.Models.Backup != c.Models.Primary {
		provider, model := splitModel(c.Models.Backup)
		policy.Fallbacks = []agentwrap.FallbackAlternative{{
			Name: "backup",
			Request: agentwrap.RunRequest{
				Provider: agentwrap.ProviderID(provider),
				Model:    agentwrap.ModelID(model),
			},
			Context: agentwrap.RuntimeContext{
				RuntimeKind: "opencode",
				RuntimeName: "opencode",
				Provider:    agentwrap.ProviderID(provider),
				Model:       agentwrap.ModelID(model),
			},
		}}
	}
	stack := agentwrap.ObservingRuntime{
		Runtime: agentwrap.ValidatingRuntime{
			Runtime: agentwrap.PolicyRunner{
				Runtime: stageRuntime,
				Policy:  missingSessionPolicy{next: policy},
			},
		},
		Policy: agentwrap.PersistencePolicy{PersistUnsafeRawPayloads: false},
	}
	adapter := Adapter{runtime: stack, health: primary}
	adapter.deleteRuntimeStore = func(_ context.Context, path string) error {
		if err := removeRuntimeStore(path); err != nil {
			markRuntimeStoreCleanupPending(path, err)
			return err
		}
		openCodeSessionCleanupMu.Lock()
		_ = pruneOpenCodeLogs(c)
		openCodeSessionCleanupMu.Unlock()
		return nil
	}
	adapter.deleteSessions = func(ctx context.Context, sessionIDs []string) error {
		openCodeSessionCleanupMu.Lock()
		defer openCodeSessionCleanupMu.Unlock()

		for _, sessionID := range sessionIDs {
			if strings.TrimSpace(sessionID) == "" {
				continue
			}
			// OpenCode stores its event stream under an aggregate whose ID is the
			// session ID, but event_sequence has no foreign key back to session.
			query := "DELETE FROM event_sequence WHERE aggregate_id = " + sqliteString(sessionID)
			if output, err := openCodeDBCommand(ctx, c, query).CombinedOutput(); err != nil {
				return fmt.Errorf("delete OpenCode session events %s: %w: %s", sessionID, err, strings.TrimSpace(string(output)))
			}
			cmd := exec.CommandContext(ctx, c.Agentwrap.Executable, "session", "delete", sessionID)
			cmd.Env = append(os.Environ(), c.Agentwrap.Env...)
			if output, err := cmd.CombinedOutput(); err != nil {
				return fmt.Errorf("delete OpenCode session %s: %w: %s", sessionID, err, strings.TrimSpace(string(output)))
			}
		}
		if err := checkpointOpenCode(ctx, c); err != nil {
			return fmt.Errorf("checkpoint OpenCode database: %w", err)
		}
		if output, err := openCodeDBCommand(ctx, c, "VACUUM").CombinedOutput(); err != nil {
			return fmt.Errorf("vacuum OpenCode database: %w: %s", err, strings.TrimSpace(string(output)))
		}
		// In WAL mode VACUUM writes the compacted image to the WAL. Checkpoint it
		// before the next worker wave starts so the temporary copy is removed.
		if err := checkpointOpenCode(ctx, c); err != nil {
			return fmt.Errorf("checkpoint vacuumed OpenCode database: %w", err)
		}
		return nil
	}
	return adapter, nil
}

type missingSessionPolicy struct {
	next agentwrap.ResiliencePolicy
}

func (p missingSessionPolicy) Decide(ctx context.Context, policyCtx agentwrap.PolicyContext) (agentwrap.PolicyDecision, error) {
	if openCodeSessionNotFound(policyCtx.Err) {
		return agentwrap.PolicyDecision{Kind: agentwrap.PolicyDecisionStop, Reason: "session not found", Detail: policyCtx.Err.UserDetail, Err: policyCtx.Err}, nil
	}
	return p.next.Decide(ctx, policyCtx)
}

func openCodeSessionNotFound(err *agentwrap.SDKError) bool {
	if err == nil {
		return false
	}
	details := []string{err.UserDetail, err.DebugDetail, err.ResponseBody}
	if err.Cause != nil {
		details = append(details, err.Cause.Error())
	}
	return strings.Contains(strings.ToLower(strings.Join(details, "\n")), "session not found")
}

func checkpointOpenCode(ctx context.Context, c config.Config) error {
	var detail string
	for attempt := 0; attempt < 20; attempt++ {
		output, err := openCodeDBCommand(ctx, c, "PRAGMA wal_checkpoint(TRUNCATE)").CombinedOutput()
		detail = strings.TrimSpace(string(output))
		if err == nil {
			fields := strings.Fields(detail)
			if len(fields) >= 3 && fields[len(fields)-3] == "0" {
				return nil
			}
		}
		if err := sleepContext(ctx, 250*time.Millisecond); err != nil {
			return err
		}
	}
	return fmt.Errorf("database remained busy: %s", detail)
}

func sleepContext(ctx context.Context, delay time.Duration) error {
	timer := time.NewTimer(delay)
	defer timer.Stop()
	select {
	case <-ctx.Done():
		return ctx.Err()
	case <-timer.C:
		return nil
	}
}

func openCodeDBCommand(ctx context.Context, c config.Config, query string) *exec.Cmd {
	cmd := exec.CommandContext(ctx, c.Agentwrap.Executable, "db", query)
	cmd.Env = append(os.Environ(), c.Agentwrap.Env...)
	return cmd
}

func sqliteString(value string) string {
	return "'" + strings.ReplaceAll(value, "'", "''") + "'"
}

// requestVariantRuntime translates UltraPlan's stage-specific variant metadata
// into an adapter invocation. agentwrap deliberately keeps request metadata
// runtime-neutral, while OpenCode exposes reasoning effort as --variant.
type requestVariantRuntime struct {
	base        agentwrap.Runtime
	withVariant func(string) agentwrap.Runtime
}

func (r requestVariantRuntime) StartRun(ctx context.Context, req agentwrap.RunRequest) (agentwrap.Run, error) {
	variant := strings.TrimSpace(req.Metadata["variant"])
	if variant == "" || r.withVariant == nil {
		return r.base.StartRun(ctx, req)
	}
	return r.withVariant(variant).StartRun(ctx, req)
}

func (r requestVariantRuntime) Capabilities(ctx context.Context) (agentwrap.Capabilities, error) {
	return r.base.Capabilities(ctx)
}

// ListModels forwards model enumeration to the primary runtime when it
// supports the optional listing capability.
func (r requestVariantRuntime) ListModels(ctx context.Context, req agentwrap.ModelsRequest) ([]agentwrap.ModelInfo, error) {
	lister, ok := r.base.(agentwrap.ModelLister)
	if !ok {
		return nil, nil
	}
	return lister.ListModels(ctx, req)
}

package runtime

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"syscall"
	"time"
)

const RuntimeStoreDirName = "runtime/opencode"

type RuntimeStoreState string

const (
	RuntimeStoreActive         RuntimeStoreState = "active"
	RuntimeStoreRetained       RuntimeStoreState = "retained"
	RuntimeStoreCleanupPending RuntimeStoreState = "cleanup_pending"
)

type RuntimeStoreRecord struct {
	SchemaVersion int               `json:"schema_version"`
	Owner         string            `json:"owner"`
	DatabasePath  string            `json:"database_path"`
	State         RuntimeStoreState `json:"state"`
	PID           int               `json:"pid,omitempty"`
	CreatedAt     time.Time         `json:"created_at"`
	UpdatedAt     time.Time         `json:"updated_at"`
	LastError     string            `json:"last_error,omitempty"`
}

type RuntimeStoreInfo struct {
	RuntimeStoreRecord
	Bytes uint64 `json:"bytes"`
}

type RuntimeStoreCleanup struct {
	Removed []RuntimeStoreInfo `json:"removed,omitempty"`
	Failed  []string           `json:"failed,omitempty"`
}

func ScopedRuntimeStorePath(scopeRoot, owner string) string {
	sum := sha256.Sum256([]byte(strings.TrimSpace(owner)))
	return filepath.Join(scopeRoot, ".ultraplan", RuntimeStoreDirName, hex.EncodeToString(sum[:16]), "opencode.db")
}

func prepareRuntimeStore(path, owner string) error {
	dir, err := validatedRuntimeStoreDir(path)
	if err != nil {
		return err
	}
	if err := os.MkdirAll(dir, 0o700); err != nil {
		return fmt.Errorf("create runtime store: %w", err)
	}
	now := time.Now().UTC()
	record := RuntimeStoreRecord{SchemaVersion: 1, Owner: owner, DatabasePath: path, State: RuntimeStoreActive, PID: os.Getpid(), CreatedAt: now, UpdatedAt: now}
	if previous, err := loadRuntimeStoreRecord(dir); err == nil {
		record.CreatedAt = previous.CreatedAt
	}
	return writeRuntimeStoreRecord(dir, record)
}

func retainRuntimeStore(path, owner string, runErr error) {
	if strings.TrimSpace(path) == "" {
		return
	}
	dir, err := validatedRuntimeStoreDir(path)
	if err != nil {
		return
	}
	record, loadErr := loadRuntimeStoreRecord(dir)
	if loadErr != nil {
		now := time.Now().UTC()
		record = RuntimeStoreRecord{SchemaVersion: 1, Owner: owner, DatabasePath: path, CreatedAt: now}
	}
	record.State = RuntimeStoreRetained
	record.PID = 0
	record.UpdatedAt = time.Now().UTC()
	if runErr != nil {
		record.LastError = runErr.Error()
	}
	_ = writeRuntimeStoreRecord(dir, record)
}

func markRuntimeStoreCleanupPending(path string, cleanupErr error) {
	dir, err := validatedRuntimeStoreDir(path)
	if err != nil {
		return
	}
	record, err := loadRuntimeStoreRecord(dir)
	if err != nil {
		return
	}
	record.State = RuntimeStoreCleanupPending
	record.PID = 0
	record.UpdatedAt = time.Now().UTC()
	if cleanupErr != nil {
		record.LastError = cleanupErr.Error()
	}
	_ = writeRuntimeStoreRecord(dir, record)
}

func removeRuntimeStore(path string) error {
	dir, err := validatedRuntimeStoreDir(path)
	if err != nil {
		return err
	}
	if err := os.RemoveAll(dir); err != nil {
		return fmt.Errorf("remove runtime store %s: %w", dir, err)
	}
	return nil
}

func validatedRuntimeStoreDir(path string) (string, error) {
	clean := filepath.Clean(strings.TrimSpace(path))
	if !filepath.IsAbs(clean) || filepath.Base(clean) != "opencode.db" {
		return "", fmt.Errorf("invalid runtime store path %q", path)
	}
	dir := filepath.Dir(clean)
	marker := string(filepath.Separator) + filepath.FromSlash(".ultraplan/"+RuntimeStoreDirName) + string(filepath.Separator)
	if !strings.Contains(dir+string(filepath.Separator), marker) {
		return "", fmt.Errorf("runtime store is outside managed storage: %q", path)
	}
	return dir, nil
}

func loadRuntimeStoreRecord(dir string) (RuntimeStoreRecord, error) {
	data, err := os.ReadFile(filepath.Join(dir, "store.json"))
	if err != nil {
		return RuntimeStoreRecord{}, err
	}
	var record RuntimeStoreRecord
	if err := json.Unmarshal(data, &record); err != nil {
		return RuntimeStoreRecord{}, err
	}
	if record.SchemaVersion != 1 {
		return RuntimeStoreRecord{}, errors.New("unsupported runtime store record")
	}
	return record, nil
}

func writeRuntimeStoreRecord(dir string, record RuntimeStoreRecord) error {
	data, err := json.MarshalIndent(record, "", "  ")
	if err != nil {
		return err
	}
	data = append(data, '\n')
	tmp, err := os.CreateTemp(dir, ".store.*.tmp")
	if err != nil {
		return err
	}
	name := tmp.Name()
	defer os.Remove(name)
	if _, err = tmp.Write(data); err == nil {
		err = tmp.Chmod(0o600)
	}
	if closeErr := tmp.Close(); err == nil {
		err = closeErr
	}
	if err != nil {
		return err
	}
	return os.Rename(name, filepath.Join(dir, "store.json"))
}

func InspectRuntimeStores(scopeRoot string) ([]RuntimeStoreInfo, error) {
	root := filepath.Join(scopeRoot, ".ultraplan", RuntimeStoreDirName)
	entries, err := os.ReadDir(root)
	if errors.Is(err, os.ErrNotExist) {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	stores := make([]RuntimeStoreInfo, 0, len(entries))
	for _, entry := range entries {
		if !entry.IsDir() {
			continue
		}
		dir := filepath.Join(root, entry.Name())
		record, err := loadRuntimeStoreRecord(dir)
		if err != nil {
			continue
		}
		stores = append(stores, RuntimeStoreInfo{RuntimeStoreRecord: record, Bytes: directoryBytes(dir)})
	}
	sort.Slice(stores, func(i, j int) bool { return stores[i].UpdatedAt.Before(stores[j].UpdatedAt) })
	return stores, nil
}

// CleanupRuntimeStores retries interrupted cleanup, expires abandoned stores,
// and optionally sacrifices retained sessions under critical disk pressure.
func CleanupRuntimeStores(scopeRoot string, maxAge time.Duration, maxBytes uint64, aggressive bool) RuntimeStoreCleanup {
	stores, err := InspectRuntimeStores(scopeRoot)
	if err != nil {
		return RuntimeStoreCleanup{Failed: []string{err.Error()}}
	}
	now := time.Now().UTC()
	var total uint64
	for _, store := range stores {
		total += store.Bytes
	}
	result := RuntimeStoreCleanup{}
	for _, store := range stores {
		staleActive := store.State == RuntimeStoreActive && !processAlive(store.PID) && now.Sub(store.UpdatedAt) > 30*time.Minute
		if staleActive {
			// A dead owner means an interrupted task, not disposable data. Keep the
			// database resumable and let the normal retention/quota policy decide
			// when it is safe to sacrifice it.
			retainRuntimeStore(store.DatabasePath, store.Owner, errors.New("runtime store owner is no longer running"))
			store.State = RuntimeStoreRetained
			store.PID = 0
			store.UpdatedAt = now
		}
		expired := store.State == RuntimeStoreRetained && maxAge > 0 && now.Sub(store.UpdatedAt) > maxAge
		overQuota := maxBytes > 0 && total > maxBytes && store.State != RuntimeStoreActive
		remove := store.State == RuntimeStoreCleanupPending || expired || overQuota || (aggressive && store.State != RuntimeStoreActive)
		if !remove {
			continue
		}
		if err := removeRuntimeStore(store.DatabasePath); err != nil {
			result.Failed = append(result.Failed, err.Error())
			continue
		}
		result.Removed = append(result.Removed, store)
		if store.Bytes <= total {
			total -= store.Bytes
		}
	}
	return result
}

func processAlive(pid int) bool {
	if pid < 1 {
		return false
	}
	return syscall.Kill(pid, 0) == nil
}

func directoryBytes(root string) uint64 {
	var total uint64
	_ = filepath.WalkDir(root, func(_ string, entry os.DirEntry, err error) error {
		if err != nil || entry.IsDir() {
			return nil
		}
		if info, statErr := entry.Info(); statErr == nil && info.Size() > 0 {
			total += uint64(info.Size())
		}
		return nil
	})
	return total
}

package runtime

import (
	"errors"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"time"

	"github.com/Antonio7098/ultraplan-go/internal/platform/config"
)

const (
	openCodeLogMaxAge   = 48 * time.Hour
	openCodeLogMaxBytes = uint64(128 * 1024 * 1024)
)

type logFile struct {
	path    string
	size    uint64
	updated time.Time
}

func pruneOpenCodeLogs(c config.Config) error {
	dataRoot := envValue(c.Agentwrap.Env, "XDG_DATA_HOME")
	if dataRoot == "" {
		home, err := os.UserHomeDir()
		if err != nil {
			return err
		}
		dataRoot = filepath.Join(home, ".local", "share")
	}
	return pruneLogDirectory(filepath.Join(dataRoot, "opencode", "log"), time.Now().UTC(), openCodeLogMaxAge, openCodeLogMaxBytes)
}

func pruneLogDirectory(root string, now time.Time, maxAge time.Duration, maxBytes uint64) error {
	entries, err := os.ReadDir(root)
	if errors.Is(err, os.ErrNotExist) {
		return nil
	}
	if err != nil {
		return err
	}
	files := make([]logFile, 0, len(entries))
	var total uint64
	for _, entry := range entries {
		if entry.IsDir() || entry.Type()&os.ModeSymlink != 0 {
			continue
		}
		info, err := entry.Info()
		if err != nil || !info.Mode().IsRegular() {
			continue
		}
		size := uint64(max(info.Size(), 0))
		files = append(files, logFile{path: filepath.Join(root, entry.Name()), size: size, updated: info.ModTime()})
		total += size
	}
	sort.Slice(files, func(i, j int) bool { return files[i].updated.Before(files[j].updated) })
	var errs []error
	for _, file := range files {
		expired := maxAge > 0 && now.Sub(file.updated) > maxAge
		// Never quota-delete a file OpenCode may still be appending to.
		overQuota := maxBytes > 0 && total > maxBytes && now.Sub(file.updated) > 10*time.Minute
		if !expired && !overQuota {
			continue
		}
		if err := os.Remove(file.path); err != nil && !errors.Is(err, os.ErrNotExist) {
			errs = append(errs, err)
			continue
		}
		if file.size <= total {
			total -= file.size
		}
	}
	return errors.Join(errs...)
}

func envValue(env []string, key string) string {
	prefix := key + "="
	for i := len(env) - 1; i >= 0; i-- {
		if strings.HasPrefix(env[i], prefix) {
			return strings.TrimSpace(strings.TrimPrefix(env[i], prefix))
		}
	}
	return ""
}

