type processSpec struct {
	Executable string
	Args       []string
	Env        []string
	WorkDir    string
	Stdin      string
}

type processResult struct {
	ExitCode int
	Err      error
}

type cleanupResult struct {
	GracefulAttempted bool
	ForceAttempted    bool
	Err               error
}

